  INSERT INTO public.subtopics (course_id, name, order_index) VALUES (c_id, 'Agent Architecture & Fundamentals', 1) RETURNING id INTO s1;
  INSERT INTO public.subtopics (course_id, name, order_index) VALUES (c_id, 'Workflow Nodes & Orchestration', 2) RETURNING id INTO s2;
  INSERT INTO public.subtopics (course_id, name, order_index) VALUES (c_id, 'Tools & Integrations', 3) RETURNING id INTO s3;
  INSERT INTO public.subtopics (course_id, name, order_index) VALUES (c_id, 'Evaluations, Security & RAG Metrics', 4) RETURNING id INTO s4;
  INSERT INTO public.questions (subtopic_id, type, question_text, options, correct_answers, explanation, difficulty) VALUES
  (s1, 'mcq', 'When is a multi-agent (with Supervisor agent) configuration most appropriate?', '["When editing static HTML pages", "When the workflow is complex, modular, or requires domain specialization", "When the task is a simple request with no dependencies", "For increasing token usage only"]'::jsonb, '[1]'::jsonb, 'Correct.', 'medium'),
  (s1, 'mcq', 'What is a primary advantage of Workflow Agents over traditional workflow engines?', '["They only execute static, linear tasks.", "They halt at every exception for user intervention.", "They can reason, adapt, and improve over time.", "They require all logic to be hard-coded in advance."]'::jsonb, '[2]'::jsonb, 'Correct.', 'medium'),
  (s1, 'mcq', 'Which of these best helps reduce hallucinations in AI Agent responses?', '["Running more hardware diagnostics", "Dynamic grounding through RAG with relevant documents", "Increasing prompt length", "Allowing access to all system data"]'::jsonb, '[1]'::jsonb, 'Correct.', 'medium'),
  (s1, 'mcq', 'Which feature ensures AI Agents only access data permitted to the user?', '["Role-based access control", "Prompt-length limitation", "Open API templates", "External plugin modules"]'::jsonb, '[0]'::jsonb, 'Correct.', 'medium'),
  (s1, 'mcq', 'Which agent component is described as being reusable, focused on a specific subject area, and aligning agent responses to certain themes?', '["Document Tool", "Supervisor agent", "Credential Store", "Topic"]'::jsonb, '[3]'::jsonb, 'Correct.', 'medium'),
  (s1, 'mcq', 'Which statement accurately describes Business Objects in AI Agent Studio?', '["They allow for text and image upload into Fusion apps.", "They act as placeholders for user interface changes.", "They are used for end user authentication and custom layout for Fusion apps.", "They provide a structure for agents to interact with Fusion data and APIs."]'::jsonb, '[3]'::jsonb, 'Correct.', 'medium');
  INSERT INTO public.questions (subtopic_id, type, question_text, options, correct_answers, explanation, difficulty) VALUES
  (s2, 'mcq', 'If you need to route your workflow to multiple possible paths based on complex conditions, which node is most suitable?', '["Switch Node", "Human Approval Node", "Set Variables Node", "Loop Node"]'::jsonb, '[0]'::jsonb, 'Correct.', 'medium'),
  (s2, 'mcq', 'What is the main function of the workflow node in a workflow agent?', '["Sends email notifications", "Calls an external API", "Runs another workflow as a subflow", "Pauses execution for human approval"]'::jsonb, '[2]'::jsonb, 'Correct.', 'medium'),
  (s2, 'mcq', 'If you need to pause the workflow agent and get a decision from a user before proceeding, which node would you choose?', '["Loop Node", "Human Approval Node", "If Condition Node", "Parallel Node"]'::jsonb, '[1]'::jsonb, 'Correct.', 'medium'),
  (s2, 'mcq', 'Which question should you ask when deciding on orchestration patterns for your workflow agents?', '["Is the workflow only for document upload tasks?", "Who will manually execute every workflow branch?", "Does the workflow need advanced graphics capabilities?", "Do I need Chaining, Switch, Parallel, Iteration, or Looping patterns?"]'::jsonb, '[3]'::jsonb, 'Correct.', 'medium'),
  (s2, 'mcq', 'What does the Human in the Loop feature enable in Agent Studio workflows?', '["Requires human review or approval before an agent takes certain actions", "Enables the setting of only read-only access for users", "Allows agents to write and approve their own changes", "Requires automatic escalation of all tasks assigned to management"]'::jsonb, '[0]'::jsonb, 'Correct.', 'medium'),
  (s2, 'mcq', 'The __________ node enables modular scaling by invoking another worker agent as a sub-process.', '["Switch", "Agent", "Code", "Document Processor"]'::jsonb, '[1]'::jsonb, 'Correct.', 'medium'),
  (s2, 'mcq', 'Which node enables the workflow to retrieve semantic context from uploaded company documents for answering questions?', '["Human Approval Node", "LLM Node", "Loop Node", "RAG Document Tool Node"]'::jsonb, '[3]'::jsonb, 'Correct.', 'medium');
  INSERT INTO public.questions (subtopic_id, type, question_text, options, correct_answers, explanation, difficulty) VALUES
  (s3, 'mcq', 'Which capability is provided by the Document Tool in AI Agent Studio?', '["Execution of payroll reports", "Dynamic UI form creation tool from a provided document", "Semantic search on uploaded unstructured documents", "Direct manipulation of image files from a provided document"]'::jsonb, '[2]'::jsonb, 'Correct.', 'medium'),
  (s3, 'mcq', 'What step is required after uploading unstructured documents for AI semantic search in the Document Tool?', '["Run the Process Agent Documents scheduled process.", "Enable Permission Groups for the document.", "Process and embed documents into the vector database.", "Share documents on public web."]'::jsonb, '[0]'::jsonb, 'Correct.', 'medium'),
  (s3, 'mcq', 'Which type of tool in Agent Studio allows integration with third-party services via API?', '["Calculator Tool", "User Session Tool", "BI Connector", "External REST Tool"]'::jsonb, '[3]'::jsonb, 'Correct.', 'medium'),
  (s3, 'msq', 'Which three tools are available in AI Agent Studio?', '["User Session Tool", "Deep Link Tool", "Hardware Scaling Tool", "Document Tool"]'::jsonb, '[0, 1, 3]'::jsonb, 'Correct.', 'medium'),
  (s3, 'mcq', 'In Agent Studio, what is a Business Object Tool used for?', '["Resizing user interface forms", "Generating marketing keywords", "Retrieving and transacting on Fusion business objects", "Processing external RSS feeds"]'::jsonb, '[2]'::jsonb, 'Correct.', 'medium');
  INSERT INTO public.questions (subtopic_id, type, question_text, options, correct_answers, explanation, difficulty) VALUES
  (s4, 'mcq', 'Which is a typical use case for using Topics in prompts?', '["Providing reusable instructions or constraints in agent prompts", "Modifying the agent s user interface in agent prompts", "Configuring additional hardware resources in agent prompts", "Initiating agent upgrades in agent prompts"]'::jsonb, '[0]'::jsonb, 'Correct.', 'medium'),
  (s4, 'mcq', 'What is the role of a Supervisor agent in a multi-agent workflow?', '["To replace all business objects", "To store company documents only", "To monitor server hardware", "To orchestrate and route tasks to worker agents"]'::jsonb, '[3]'::jsonb, 'Correct.', 'medium'),
  (s4, 'mcq', 'What new RAG evaluation metrics are included in agent evaluations in AI Agent Studio?', '["Token usage, latency, and server uptime", "Encryption strength, user authentication, and key rotation", "Prompt length, model temperature, and top-p", "Groundedness (Faithfulness), Answer Relevance, and Context Relevance"]'::jsonb, '[3]'::jsonb, 'Correct.', 'medium'),
  (s4, 'mcq', 'When should evaluations of AI agents be rerun, according to METRO best practices?', '["After an agent''s code is deleted", "Only before initial deployment", "After any changes to the agent or model updates", "Whenever the dashboard displays an error"]'::jsonb, '[2]'::jsonb, 'Correct.', 'medium'),
  (s4, 'mcq', 'In the world described, how are business objects, roles, and workflows incorporated into Oracle Application?', '["They require separate dashboards.", "They are partially integrated using APIs.", "They are natively part of the application.", "They are managed through manual entry."]'::jsonb, '[2]'::jsonb, 'Correct.', 'medium'),
  (s4, 'mcq', 'What is the main purpose of a summarization prompt in Agent Studio?', '["To manage user notifications in AI Agent Studio", "To initiate a file upload in the end user session", "To instruct the AI agent to condense information into a concise output", "To increase the number of fields available"]'::jsonb, '[2]'::jsonb, 'Correct.', 'medium'),
  (s4, 'msq', 'When evaluating agent performance, ________ indicates the time taken by the model to generate responses, which is a key performance metric.', '["Latency", "Correctness", "Token", "Safety"]'::jsonb, '[0, 1]'::jsonb, 'Correct.', 'medium'),
  (s4, 'mcq', 'When configuring security in the Agent Studio post-25C upgrade, what must be enabled before the Security Console can assign custom roles for AI Studio?', '["Permission Groups", "BI Reporting Modules", "Real-Time Auditing", "Backup Scheduling"]'::jsonb, '[0]'::jsonb, 'Correct.', 'medium');
  INSERT INTO public.courses (name, description, icon)
  INSERT INTO public.subtopics (course_id, name, order_index) VALUES (c_id, 'Introduction and Configuration', 1) RETURNING id INTO s1;
  INSERT INTO public.subtopics (course_id, name, order_index) VALUES (c_id, 'Workspace Design and Setup', 2) RETURNING id INTO s2;
  INSERT INTO public.subtopics (course_id, name, order_index) VALUES (c_id, 'Machine Learning Life Cycle', 3) RETURNING id INTO s3;
  INSERT INTO public.subtopics (course_id, name, order_index) VALUES (c_id, 'MLOps Practices', 4) RETURNING id INTO s4;
  INSERT INTO public.subtopics (course_id, name, order_index) VALUES (c_id, 'Related OCI Services', 5) RETURNING id INTO s5;
  INSERT INTO public.questions (subtopic_id, type, question_text, options, correct_answers, explanation, difficulty) VALUES
  (s1, 'mcq', 'Which feature of Oracle Cloud Infrastructure Data Science provides an interactive coding environment for building and training machine learning models?', '["Model catalog", "Projects", "Notebook session", "Jobs"]'::jsonb, '[2]'::jsonb, 'OCI Notebook sessions are interactive coding environments for building and training models. A Notebook session is created inside a Data Science project.', 'medium'),
  (s1, 'mcq', 'Which allows the sharing and loading back of ML models into a Notebook session?', '["Model catalog", "Model taxonomy", "Model provenance", "Model deployment"]'::jsonb, '[0]'::jsonb, 'The model catalog is a centralized and managed repository of model artifacts. A stored model includes metadata about the provenance of the model including Git-related information and the script or notebook used to push the model to the catalog. Models stored in the model catalog can be shared across members of a team and they can be loaded back into a Notebook session.', 'medium'),
  (s1, 'mcq', 'What is feature engineering in machine learning used for?', '["To help understand the data set features", "To perform parameter tuning", "To represent the data in a way that helps the model learn more effectively (Correct \u2013 Your", "To interpret ML models"]'::jsonb, '[2]'::jsonb, 'Feature engineering is used to represent the data in a way that helps the model learn more effectively.', 'medium'),
  (s1, 'mcq', 'Which OCI Data Science interaction method can function in both ways — with or without the need of scripting?', '["Language SDKs", "OCI Console", "REST API", "CLI"]'::jsonb, '[1]'::jsonb, 'The OCI Console offers interaction with the Data Science service without the need for scripts.', 'medium'),
  (s1, 'mcq', 'What does the Data Science Service template in Oracle Resource Manager (ORM) NOT automatically create?', '["Dynamic groups", "Policies for a basic use case", "Required user groups", "Individual Data Science users"]'::jsonb, '[3]'::jsonb, 'Oracle Resource Manager (ORM) automatically creates the policies for a basic use case, required user groups, and dynamic groups. It doesn’t create individual Data Science users. Workspace Design and Setup 8 Questions', 'medium');
  INSERT INTO public.questions (subtopic_id, type, question_text, options, correct_answers, explanation, difficulty) VALUES
  (s2, 'mcq', 'What happens when a notebook session is deactivated?', '["The data on the boot volume is not preserved.", "Compute cost increases due to frequent deactivation.", "The underlying compute instance stops.", "The block volume attached to the Notebook session is permanently deleted."]'::jsonb, '[2]'::jsonb, 'When you deactivate a Notebook session, you save on compute costs because the underlying compute instance stops, and the block volume is detached and preserved.', 'medium'),
  (s2, 'mcq', 'Which is a unique feature of the published Conda environment?', '["It provides availability on Notebook session reactivation.", "It provides a comprehensive environment to solve business use cases.", "It allows you to save the Conda environment in a block volume.", "It allows you to save the Conda environment to an Object Storage bucket."]'::jsonb, '[3]'::jsonb, 'Published Conda environments are customer-created and saved to Object Storage buckets. This is the most unique feature of the published Conda environment.', 'medium'),
  (s2, 'mcq', 'Where are OCI secrets stored?', '["Autonomous Data Warehouse", "OCI Vault", "OCI Object Storage", "Oracle Databases"]'::jsonb, '[1]'::jsonb, 'Secrets are credentials such as passwords or tokens--or any other confidential data that you need to use with other Oracle Cloud Infrastructure services--or perhaps even other external applications or systems. They are stored in OCI Vault.', 'medium'),
  (s2, 'mcq', 'Which CLI command allows a customized Conda environment to be shared with co-workers?', '["odsc conda modify", "odsc conda publish", "odsc conda install", "odsc conda clone"]'::jsonb, '[1]'::jsonb, 'Publishing a Conda environment consists of creating a pack of a Conda environment and uploading it to a specified Object Storage. This allows Conda environments to be shared among colleagues or to persist them across Notebook sessions.', 'medium'),
  (s2, 'mcq', 'Which activity of managing a conda environment requires the conda environment to be activated in your terminal?', '["Installing a Conda environment", "Publishing a Conda environment", "Modifying a Conda environment", "Cloning a Conda environment"]'::jsonb, '[2]'::jsonb, 'To modify the libraries in the Conda environment, it must remain active.', 'medium'),
  (s2, 'mcq', 'What is a conda environment?', '["An open source package and environment management system", "An environment deployment system on Oracle AI", "A collection of kernels", "A system that manages package independencies"]'::jsonb, '[0]'::jsonb, 'Conda is an open source package management system and environment management system. Conda as a package manager helps you find and install packages.', 'medium'),
  (s2, 'mcq', 'Which model has an open source, open model format that allows you to run machine learning models on different platforms?', '["TensorFlow", "ONNX", "PyTorch", "PySpark"]'::jsonb, '[1]'::jsonb, 'ONNX is an open source, open model package that allows you to save a model from different machine learning (ML) libraries into a single, portable format that is independent of the training library. TensorFlow and PyTorch are open source ML frameworks for deep neural networks. PySpark is a framework used for processing a huge amount of data. Machine Learning Life Cycle 6 Questions', 'medium');
  INSERT INTO public.questions (subtopic_id, type, question_text, options, correct_answers, explanation, difficulty) VALUES
  (s3, 'mcq', 'Which function represents the difference between the predictive value and the target value?', '["Fit function", "Update function", "Cost function", "Optimizer function"]'::jsonb, '[2]'::jsonb, 'The objective of the loss function is to represent the difference between the predicted values Ŷ and the true targets Y as a single number, the loss score. The loss function is also known as the cost function.', 'medium'),
  (s3, 'mcq', 'Which stage in the machine learning life cycle helps identify imbalances present in data?', '["Data Modeling", "Data Exploration", "Data Monitoring", "Data Access"]'::jsonb, '[1]'::jsonb, 'The process of building and breaking the ML model has six steps. Of these, Data Exploration is used to cleanse the data by identifying corrupt, inaccurate, and incomplete data and replacing or deleting it. This also helps in identifying the imbalances present in the data.', 'medium'),
  (s3, 'mcq', 'You are working for a bank. You are required to analyze customer accounts'' access data and flag any irregular access attempts. Which OCI Data Science operator are you most likely to use?', '["Forecasting", "PII", "Anomaly"]'::jsonb, '[2]'::jsonb, 'Anomaly detection is used for finding anomalies or any irregularities in your data.', 'medium'),
  (s3, 'mcq', 'Which step is a part of AutoML pipeline?', '["Feature Extraction", "Model Saved to Model Catalog", "Feature Selection", "Model Deployment"]'::jsonb, '[2]'::jsonb, 'Oracle AutoML automates four major steps in the machine learning modeling process to deliver significant productivity improvements for data scientists. They are Algorithm Selection, Adaptive Sampling, Feature Selection, and Model Tuning.', 'medium'),
  (s3, 'mcq', 'What do you use the score.py file for?', '["Defining the scaling strategy", "Defining the required Conda environments", "Executing the inference logic code", "Configuring the deployment infrastructure"]'::jsonb, '[2]'::jsonb, 'This file contains the function definitions that are necessary to load your model to memory and make predictions. The two functions are called load_model() and predict(). The function parameters are not customizable. For example, you can define data transformations in predict() before calling the inference method of your estimator object. In other words, it is used for executing the inference logic code.', 'medium'),
  (s3, 'mcq', 'Which activity is NOT a part of the machine learning life cycle?', '["Database Management", "Model Deployment", "Modeling", "Data Access"]'::jsonb, '[0]'::jsonb, 'The machine learning life cycle has six important tasks: Data Access, Data Exploration and Data Preparation, Modeling, Validation, Model Deployment, and Monitoring/Refresh/Retirement. Database Management is not a part of this life cycle. MLOps Practices 8 Questions', 'medium');
  INSERT INTO public.questions (subtopic_id, type, question_text, options, correct_answers, explanation, difficulty) VALUES
  (s4, 'mcq', 'Which statement us true about machine learning models?', '["A high-quality model will not need to be retrained as new information is received.", "Static predictions become increasingly accurate over time.", "Model performance degrades over time due to changes in data.", "Data models are more static and generally require fewer updates than software code."]'::jsonb, '[2]'::jsonb, 'Machine learning models are data driven. Whenever the data changes, the model needs retraining. Else the performance degrades over time.', 'medium'),
  (s4, 'mcq', 'Which step is unique to MLOps, as opposed to DevOps?', '["Continuous Training", "Continuous Integration", "Continuous Deployment", "Continuous Delivery"]'::jsonb, '[0]'::jsonb, 'Continuous Training is unique to MLOps and refers to the automatic retraining of ML models for redeployment.', 'medium'),
  (s4, 'mcq', 'In the OCI Console, as part of Monitoring, of what is triggering a Pager Duty notification an example?', '["Event", "Action", "Rule", "Function"]'::jsonb, '[1]'::jsonb, 'Action is a user-defined response to an event, such as triggering a notification. Triggering a Pager Duty notification in this case is an example of Action.', 'medium'),
  (s4, 'mcq', 'Which statement is true about logs for Oracle Cloud Infrastructure Jobs?', '["Integrating Data Science Jobs resources with Logging is mandatory.", "Logs are automatically deleted when the job and job run are deleted.", "All stdout and stderr are automatically stored when automatic log creation is enabled. (Correct", "Each job run sends outputs to a single log for that job."]'::jsonb, '[2]'::jsonb, 'When working with custom logs, the customer captures log events collected in a particular context. Here the standard output (stdout) and standard error (stderr) outputs from job artifacts are automatically captured.', 'medium'),
  (s4, 'mcq', 'As a data scientist, you require a pipeline to train ML models. When can a pipeline run be initiated?', '["After the Active state", "After it is created", "During the pipeline run state", "Before the Active state"]'::jsonb, '[0]'::jsonb, 'A pipeline life cycle has four states: Create, Active, Run, and Delete. The pipeline run state gets initiated after the active state.', 'medium'),
  (s4, 'mcq', 'Why would you use a mini batch when processing a job in Data Science Jobs?', '["You do not need to process data quickly.", "You want several distributed models to run simultaneously.", "You want to process data frequently.", "There is a small amount of total data to process."]'::jsonb, '[2]'::jsonb, 'Sometimes so much data comes in or needs to be processed so quickly that a mini batch is preferable. This is a set of more frequent job runs that processes a smaller amount of data at a time. A good example of when to use a mini batch is a bank analyzing transactions to search for fraud. Every several minutes, a job is run that takes data from Object Storage and looks for fraudulent transactions.', 'medium'),
  (s4, 'mcq', 'Which statement is true about Oracle Cloud Infrastructure Data Science Jobs?', '["Jobs provisions the infrastructure to run a process on demand.", "Jobs comes with a set of standard tasks that cannot be customized.", "You must use a single Shell/Bash or Python artifact to run a job.", "You must create and manage your own Jobs infrastructure."]'::jsonb, '[0]'::jsonb, 'A job is a template that describes the task. In each job run, you can override some of the job configuration, and most importantly, the environment variables and CLI arguments. You can have the same job with several sequentially or simultaneously started job runs with different parameters.', 'medium');
  INSERT INTO public.questions (subtopic_id, type, question_text, options, correct_answers, explanation, difficulty) VALUES
  (s5, 'mcq', 'What is the name of the machine learning library used in Apache Spark?', '["GraphX", "Structured Streaming", "MLlib", "HadoopML"]'::jsonb, '[2]'::jsonb, 'PySpark 3.2 and the Big Data service leverage the power of Apache Spark and MLlib to speed up model building.', 'medium'),
  (s5, 'mcq', 'Which option indicates the three types of data used for Data Labeling?', '["Image, text, document", "Image, audio, document", "Graphic, text, document", "Text, audio, video"]'::jsonb, '[0]'::jsonb, 'Data Labeling is the process of identifying properties (labels) of documents, text, and images (records), and annotating (labeling) them with those properties.', 'medium'),
  (s5, 'mcq', 'You are a researcher who requires access to large data sets. Which OCI service would you use?', '["ADW", "OCI Data Science", "Oracle Databases", "Oracle Open Data"]'::jsonb, '[3]'::jsonb, 'Oracle Open Data is a service from Oracle for Research that makes large data sets available to researchers around the world. It curates information like spatial images, protein sequences, and annotated text files from the world’s leading scientific data sources.', 'medium'),
  (s5, 'mcq', 'Which OCI service provides a scalable environment for developers and data scientists to run Apache Spark applications at scale?', '["Data Flow", "Anomaly Detection", "Data Science", "Data Labeling"]'::jsonb, '[0]'::jsonb, 'Oracle Cloud Infrastructure Data Flow is a fully managed service for running Apache Spark applications. It allows developers to focus on their applications and provides an easy runtime environment to execute them. It has a simple user interface with API support for integration with applications and workflows.', 'medium');
